mapper.select:
SELECT p.*, u.nickname AS nickname, u.is_author AS is_author, (SELECT COUNT(*) FROM Comments c WHERE c.post_id = p.post_id) AS comment_count FROM Posts p JOIN integrated_user u ON p.user_id = u.user_id WHERE p.board_id = #{boardId}
AND p.platform_tag = #{tag}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.created_at DESC

mapper.update:
UPDATE Posts
SET title = #{title}, content = #{content}, platform_tag = #{tag}
WHERE post_id = #{postId} AND user_id = #{userId}
